def org(id_, en, es, sci, desc, taxonomy=None, tissue='whole organism', organelle='cytoplasm'):
    return dict(id=id_, name=B(en, es), sci=sci, desc=desc, taxonomy=taxonomy or ['Eukaryota'], tissue=tissue, organelle=organelle)

