def inh_common(id_, title, subtitle, diff, minutes, objective, description, organism, explore, inherit, hints, done_title, summary, impact, case, context, simplify, refs, kind):
    return dict(id=id_, mode='inherit', kind=kind, title=title, subtitle=subtitle, difficulty=diff, minutes=minutes, objective=objective, description=description,
                organism=organism, exploration=explore, inherit=inherit, product=B('Probability', 'Probabilidad'),
                steps=[(B('Parents', 'Progenitores'), B('Each gives one allele.', 'Cada uno da un alelo.')), (B('Square', 'Cuadro'), B('All combinations.', 'Todas las combinaciones.')), (B('Trait', 'Rasgo'), B('Read the result.', 'Lee el resultado.'))],
                hints=hints, done_title=done_title, summary=summary, impact=impact, case=case, context=context, simplify=simplify, refs=refs)

