# ═════════════════════════ MUTATION ═════════════════════════

def mut(id_, title, subtitle, diff, minutes, gene, reference, mutant, story, expl, explore, hints, kind, organism, done_title, summary, impact, case, context):
    return dict(id=id_, mode='mutation', kind=kind, title=title, subtitle=subtitle, difficulty=diff, minutes=minutes,
                objective=B('Find the letter that changed in the gene and say what the change does to the protein.', 'Encuentra la letra que ha cambiado en el gen y di qué efecto tiene en la proteína.'),
                description=B('A change of one letter in DNA can change an amino acid, cut a protein short, or do nothing at all. Compare the two sequences codon by codon.',
                              'Un cambio de una letra en el ADN puede cambiar un aminoácido, cortar una proteína o no hacer nada. Compara las dos secuencias codón a codón.'),
                organism=organism, exploration=explore,
                mutation=dict(gene=gene, reference=reference, mutant=mutant, story=story, explanations=expl),
                product=B('Effect', 'Efecto'), steps=[(B('Compare', 'Comparar'), B('Find the changed letter.', 'Encuentra la letra cambiada.')), (B('Translate', 'Traducir'), B('Read the codons.', 'Lee los codones.')), (B('Effect', 'Efecto'), B('Decide what it does.', 'Decide qué hace.'))],
                hints=hints, done_title=done_title, summary=summary, impact=impact, case=case, context=context,
                simplify=[B('The sequence is an invented, short example, not a real gene.', 'La secuencia es un ejemplo inventado y corto, no un gen real.')], refs=[])

def cod(s):
    return ' '.join(s[i:i + 3] for i in range(0, len(s), 3))

